package com.ridex.location.controller;
import com.ridex.location.dto.response.NearbyDriverResponse; import com.ridex.location.service.DriverLocationService; import org.junit.jupiter.api.Test; import org.springframework.http.HttpStatus; import java.util.*; import static org.junit.jupiter.api.Assertions.*; import static org.mockito.Mockito.*;
class DriverSearchControllerTest { @Test void returnsNearbyDrivers(){ DriverLocationService service=mock(DriverLocationService.class); DriverSearchController controller=new DriverSearchController(service); UUID id=UUID.randomUUID(); List<NearbyDriverResponse> expected=List.of(new NearbyDriverResponse(id,1.25)); when(service.findNearbyDrivers(12.0,77.0,5.0)).thenReturn(expected); var response=controller.findNearbyDrivers(12,77,5); assertEquals(HttpStatus.OK,response.getStatusCode()); assertEquals(expected,response.getBody()); verify(service).findNearbyDrivers(12,77,5); } @Test void returnsEmptyListWhenNoDrivers(){ DriverLocationService service=mock(DriverLocationService.class); DriverSearchController controller=new DriverSearchController(service); when(service.findNearbyDrivers(0,0,1)).thenReturn(List.of()); assertTrue(controller.findNearbyDrivers(0,0,1).getBody().isEmpty()); } }
